  dshMotSomeoneILove: { en: "Someone I love", es: "Alguien a quien quiero", ru: "Близкий человек", fr: "Quelqu'un que j'aime", de: "Jemand, den ich liebe", pt: "Alguém que amo", it: "Una persona che amo", ja: "大切な人", zh: "我爱的人" },
